READERS = {"order-created": OrderCreated, "order-shipped": OrderShipped}

def handle(msg):                       # msg.headers() is a list of (key, value) pairs
    token = dict(msg.headers()).get("content-type", b"").decode()
    model = READERS.get(token)
    if model is None:
        raise ValueError(f"unknown message type {token!r}")
    return model.model_validate_json(msg.value())
